"""Brute-force reference analyzer for tiny instances (validation only)."""
import sys, itertools
from fractions import Fraction
from math import lcm

sys.path.insert(0, '/workspace/submission')
import analyze as A


class Skip(Exception):
    pass


def prep(inst):
    edges = inst['edges']; coms = inst['commodities']; snaps = inst['snapshots']
    domains = inst['domains']
    S = len(snaps); C = len(coms); E = len(edges)
    W = []
    coef = []
    for (_cid, _s, _t, routes) in coms:
        row = [0] * E
        wsum = 0
        for path, w in routes:
            wsum += w
            for ei in path:
                row[ei] += w
        W.append(wsum); coef.append(row)
    L = 1
    for w in W:
        L = lcm(L, w)
    Asc = [[coef[c][e] * (L // W[c]) for e in range(E)] for c in range(C)]
    return edges, coms, snaps, domains, S, C, E, W, Asc, L


def ref_analyze(inst, limit=400000):
    edges, coms, snaps, domains, S, C, E, W, Asc, L = prep(inst)
    dom_idx = {d: i for i, d in enumerate(domains)}
    nd = len(domains)
    cid_index = {c[0]: i for i, c in enumerate(coms)}
    eid_index = {e[0]: i for i, e in enumerate(edges)}

    per = []
    for s in range(S):
        bnd = snaps[s][1]
        obs = snaps[s][4]
        ranges = [range(lo, hi + 1) for (lo, hi) in bnd]
        groups = {}
        n = 1
        for r in ranges:
            n *= len(r)
            if n > 400000:
                raise Skip()
        if C == 0:
            combos = [()]
        else:
            combos = itertools.product(*ranges)
        for combo in combos:
            qrow = list(combo)
            loads = [sum(qrow[c] * Asc[c][e] for c in range(C) if Asc[c][e]) for e in range(E)]
            if any(loads[e] > L * edges[e][3] for e in range(E)):
                continue
            ing = {}
            egr = {}
            for ci, (_cid, src, tgt, _r) in enumerate(coms):
                ing[src] = ing.get(src, 0) + qrow[ci]
                egr[tgt] = egr.get(tgt, 0) + qrow[ci]
            ok = True
            mask = 0
            for (_oid, metric, target, lo, hi, dom) in obs:
                if metric == 'demand':
                    val = qrow[cid_index[target]]
                elif metric == 'link':
                    val = Fraction(loads[eid_index[target]], L)
                elif metric == 'ingress':
                    val = ing.get(target, 0)
                else:
                    val = egr.get(target, 0)
                if not (lo <= val <= hi):
                    if dom is None:
                        ok = False
                        break
                    mask |= (1 << dom_idx[dom])
            if not ok:
                continue
            groups.setdefault(mask, []).append((qrow, loads))
        per.append(groups)

    reach = [None] * (S + 1)
    reach[S] = frozenset([0])
    for i in range(S - 1, -1, -1):
        nxt = set()
        for u in reach[i + 1]:
            for m in per[i]:
                nxt.add(u | m)
        reach[i] = frozenset(x for x in nxt if bin(x).count('1') <= max(0, inst['max_faults']))
    if not reach[0]:
        return ({'id': None, 'status': 'infeasible'}, None)
    k = min(bin(u).count('1') for u in reach[0])
    kk = k

    dmin = [[None] * C for _ in range(S)]
    dmax = [[None] * C for _ in range(S)]
    lmin = [[None] * E for _ in range(S)]
    lmax = [[None] * E for _ in range(S)]
    any_agree = [False] * S
    all_agree = [True] * S
    any_fault = [False] * nd
    all_fault = [True] * nd
    first = None
    same = True
    count = 0
    members = []

    def dfs(i, union, chosen):
        nonlocal first, same, count
        if i == S:
            count += 1
            if count > limit:
                raise Skip()
            for s in range(S):
                qrow = chosen[s]
                for c in range(C):
                    v = qrow[c]
                    if dmin[s][c] is None or v < dmin[s][c]:
                        dmin[s][c] = v
                    if dmax[s][c] is None or v > dmax[s][c]:
                        dmax[s][c] = v
                ctrl = snaps[s][2]; tol = snaps[s][3]
                if all(abs(qrow[c] - ctrl[c]) <= tol for c in range(C)):
                    any_agree[s] = True
                else:
                    all_agree[s] = False
            for d in range(nd):
                if union & (1 << d):
                    any_fault[d] = True
                else:
                    all_fault[d] = False
            if first is None:
                first = [list(r) for r in chosen]
                members.append(([list(r) for r in chosen], union))
            elif same and first != chosen:
                same = False
            if len(members) < 40 and first != chosen:
                members.append(([list(r) for r in chosen], union))
            return
        for m, vecs in per[i].items():
            nu = union | m
            if bin(nu).count('1') > kk:
                continue
            good = False
            for v in reach[i + 1]:
                if bin(nu | v).count('1') == kk:
                    good = True
                    break
            if not good:
                continue
            for (vec, _ld) in vecs:
                chosen.append(vec)
                dfs(i + 1, nu, chosen)
                chosen.pop()

    dfs(0, 0, [])

    snaps_out = []
    for s in range(S):
        ctrl = snaps[s][2]; tol = snaps[s][3]
        if C == 0:
            verdict = 'consistent'
        else:
            verdict = ('consistent' if all_agree[s]
                       else ('inconsistent' if not any_agree[s] else 'undetermined'))
        snaps_out.append({
            'id': snaps[s][0],
            'demands': [[dmin[s][c], dmax[s][c]] for c in range(C)],
            'links': [[ '%d/%d' % ((Fraction(lmin[s][e], L)).numerator,
                                   (Fraction(lmin[s][e], L)).denominator),
                        '%d/%d' % ((Fraction(lmax[s][e], L)).numerator,
                                   (Fraction(lmax[s][e], L)).denominator)] for e in range(E)],
            'verdict': verdict,
        })
    out = {
        'status': 'unique' if same else 'ambiguous',
        'min_faults': kk,
        'faults': {
            'forced': [domains[d] for d in range(nd) if all_fault[d]],
            'possible': [domains[d] for d in range(nd) if any_fault[d]],
        },
        'snapshots': snaps_out,
    }
    return out, {'count': count, 'members': members, 'first': first}


if __name__ == '__main__':
    import json
    for line in sys.stdin:
        req = json.loads(line)
        if 'version' not in req:
            print(json.dumps({'id': None, 'status': 'error', 'error': 'invalid_instance'}))
            continue
        rid = req.get('id')
        try:
            inst = A._parse_request(req)
            res, stats = ref_analyze(inst)
            res['id'] = rid
        except Exception as e:
            import traceback; traceback.print_exc()
            res = {'id': rid, 'status': 'error', 'error': 'invalid_instance'}
        print(json.dumps(res))
